                    f"  = {format_money(line.total_cents, order.currency):>12}")
    if order.discount_percent > 0:
        rows.append(f"{'DISCOUNT (' + str(order.discount_percent) + '%)':<36}{format_money(order.discount_cents, order.currency):>12}")
    rows.append(f"{'TOTAL':<36}{format_money(order.total_cents, order.currency):>12}")
    return "\n".join(rows)
